/* Optional browser-voice reading for text actually displayed by WebAddress.
 * The visual timeline is reading progress, never an acoustic waveform or
 * a claim that this publisher supplied a recorded narration. */
#ifndef BONFYRE_ARTICLE_LISTEN_H
#define BONFYRE_ARTICLE_LISTEN_H
#include "editorial_soundtrack.h"
static void bf_article_listen_emit(FILE *out) {
    fputs(
    "<section class=\"bf-article-listen\" data-article-listen hidden role=\"region\" aria-label=\"Listen to this page's available text\">\n"
    "<div class=\"bf-listen-heading\"><div><span class=\"bf-listen-label\">Aurekai listening</span><h2>Listen to this summary</h2></div><span data-listen-length></span></div>\n"
    "<div class=\"bf-listen-controls\"><button type=\"button\" data-listen-play aria-label=\"Play the article summary\">▶ Play</button><button type=\"button\" data-listen-back aria-label=\"Previous passage\">Previous</button><button type=\"button\" data-listen-next aria-label=\"Next passage\">Next</button><label for=\"bf-listen-speed\">Speed <select id=\"bf-listen-speed\" data-listen-speed><option value=\"0.85\">0.85×</option><option value=\"1\" selected>1×</option><option value=\"1.25\">1.25×</option><option value=\"1.5\">1.5×</option><option value=\"2\">2×</option></select></label></div>\n"
    "<div class=\"bf-listen-soundtrack\"><label for=\"bf-listen-music\">Background music <select id=\"bf-listen-music\" data-listen-music><option value=\"auto\" selected>Editorial mix · automatic</option><option value=\"0\">Warm keys</option><option value=\"1\">Radio pulse</option><option value=\"2\">Evening lounge</option><option value=\"3\">Reflective drift</option><option value=\"4\">Soft interlude</option><option value=\"off\">Off</option></select></label><small>Original instrumental score; voice stays in front.</small></div>\n"
    "<progress class=\"bf-listen-timeline\" data-listen-timeline max=\"100\" value=\"0\" aria-label=\"Reading progress\">0%</progress>\n"
    "<div class=\"bf-listen-status\"><span data-listen-progress>Ready to listen</span><span data-listen-status role=\"status\" aria-live=\"polite\"></span></div>\n"
    "<small>This reads the text available on this page using your browser's voice. It is not a publisher-recorded narration; voice processing depends on your browser.</small></section>\n",out);
    fputs(
    "<script>(function(){\n"
    "'use strict';\n"
    "const script=document.currentScript,root=script.previousElementSibling;\n"
    "const initialize=()=>{\n"
    "if(!root||!root.matches('[data-article-listen]')||!('speechSynthesis' in window)||!('SpeechSynthesisUtterance' in window))return;\n"
    "const site=root.closest('[data-article-listen-scope=\"site\"]');\n"
    "const article=site?root.closest('.site-composition'):root.closest('.thing-text'),heading=article?.querySelector('h1');\n"
    "const selector=site?'.site-page > p.lede, .site-page > section:not(.bf-article-recording):not(.site-article-sources):not(.offer) p, .site-page > section:not(.bf-article-recording):not(.site-article-sources):not(.offer) h2, .site-page > section:not(.bf-article-recording):not(.site-article-sources):not(.offer) blockquote':':scope > p.thing-body';\n"
    "const nodes=article?[...article.querySelectorAll(selector)].filter(n=>!root.contains(n)&&n.textContent.trim()):[];\n"
    "if(!heading||!nodes.length)return;\n"
    "if(site)root.querySelector('h2').textContent='Listen to this article';\n"
    "const entries=[{node:null,text:heading.textContent.trim()},...nodes.map(node=>({node,text:node.textContent.trim()}))].filter(e=>e.text);\n"
    "const engine=window.speechSynthesis,play=root.querySelector('[data-listen-play]'),back=root.querySelector('[data-listen-back]'),next=root.querySelector('[data-listen-next]'),speed=root.querySelector('[data-listen-speed]'),progress=root.querySelector('[data-listen-progress]'),status=root.querySelector('[data-listen-status]'),timeline=root.querySelector('[data-listen-timeline]');\n"
    "let current=0,fraction=0,run=0,state='idle',disposed=false,utterance=null;\n"
    BF_EDITORIAL_SCORE_JS
    "const soundtrack=typeof bfEditorialSoundtrack==='function'?bfEditorialSoundtrack(root,heading.textContent):{start(){},duck(){},pause(){},end(){},change(){},dispose(){}};\n"
    "const total=entries.reduce((sum,e)=>sum+e.text.split(/\\s+/u).length,0);\n"
    "root.querySelector('[data-listen-length]').textContent='About '+Math.max(1,Math.ceil(total/165))+' min';\n"
    "function render(){\n"
    " const ratio=state==='done'?1:(current+fraction)/entries.length;\n"
    " const complete=Math.round(Math.min(1,Math.max(0,ratio))*100);\n"
    " timeline.value=complete;\n"
    " progress.textContent=state==='done'?'Finished':(current+1)+' of '+entries.length+' passages · '+complete+'%';\n"
    " play.textContent=state==='playing'?'Ⅱ Pause':state==='paused'?'▶ Resume':'▶ Play';\n"
    " play.setAttribute('aria-label',state==='playing'?'Pause reading':state==='paused'?'Resume reading':'Play '+(site?'article':'article summary'));\n"
    " back.disabled=current===0&&state!=='done';next.disabled=current>=entries.length-1;\n"
    " entries.forEach((e,i)=>{if(e.node){if(i===current&&state==='playing')e.node.setAttribute('data-listen-active','');else e.node.removeAttribute('data-listen-active');}});\n"
    "}\n"
    "function halt(){run++;engine.cancel();utterance=null;state='idle';}\n"
    "function begin(at){\n"
    " if(disposed||at<0||at>=entries.length)return;\n"
    " halt();current=at;fraction=0;const ticket=run;\n"
    " if(typeof window.CustomEvent==='function'&&typeof document.dispatchEvent==='function')document.dispatchEvent(new window.CustomEvent('bonfyre:public-audio-play',{detail:root}));\n"
    "    soundtrack.start();\n"
    " utterance=new SpeechSynthesisUtterance(entries[current].text);\n"
    " utterance.lang=document.documentElement.lang||'en-US';utterance.rate=Number(speed.value);\n"
    "    utterance.onstart=()=>{if(ticket!==run)return;state='playing';soundtrack.duck(true);status.textContent='Reading with device voice';render();};\n"
    " utterance.onboundary=event=>{if(ticket!==run)return;fraction=Math.min(.98,Math.max(0,event.charIndex/Math.max(1,entries[current].text.length)));render();};\n"
    "    utterance.onend=()=>{if(ticket!==run||disposed)return;soundtrack.duck(false);if(current+1<entries.length)begin(current+1);else{soundtrack.end();state='done';fraction=1;status.textContent='Reading complete';render();}};\n"
    "    utterance.onerror=event=>{if(ticket!==run)return;soundtrack.end();state='idle';status.textContent=event.error==='not-allowed'?'Enable speech playback in your browser.':'Browser voice is unavailable for this passage.';render();};\n"
    " state='playing';status.textContent='Preparing browser voice…';render();engine.speak(utterance);\n"
    "}\n"
    "function toggle(){\n"
    " if(disposed)return;\n"
    "    if(state==='playing'){engine.pause();soundtrack.pause();state='paused';status.textContent='Paused';render();}\n"
    "    else if(state==='paused'){engine.resume();soundtrack.start();soundtrack.duck(true);state='playing';status.textContent='Reading with device voice';render();}\n"
    " else begin(state==='done'?0:current);\n"
    "}\n"
    "    function dispose(){if(disposed)return;disposed=true;halt();soundtrack.dispose();entries.forEach(e=>e.node?.removeAttribute('data-listen-active'));}\n"
    "play.addEventListener('click',toggle);\n"
    "back.addEventListener('click',()=>begin(state==='done'?entries.length-1:Math.max(0,current-1)));\n"
    "next.addEventListener('click',()=>begin(Math.min(entries.length-1,current+1)));\n"
    "speed.addEventListener('change',()=>{if(state==='playing'||state==='paused')begin(current);});\n"
    "    root.querySelector('[data-listen-music]')?.addEventListener('change',()=>soundtrack.change(state==='playing'));\n"
    "root.addEventListener('keydown',event=>{if(event.target===root&&event.code==='Space'){event.preventDefault();toggle();}});\n"
    "window.addEventListener('pagehide',dispose,{once:true});\n"
    "document.addEventListener('htmx:beforeCleanupElement',event=>{if(event.detail?.elt?.contains(root))dispose();});\n"
    "    document.addEventListener('bonfyre:public-audio-play',event=>{if(event.detail!==root&&(state==='playing'||state==='paused')){halt();soundtrack.end();status.textContent='Stopped for another recording';render();}});\n"
    "root.hidden=false;status.textContent='Ready when you are';render();\n"
    "};\n"
    "if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initialize,{once:true});else initialize();\n"
    "})();</script>\n",out);
}
#endif
